--
-- Table structure for table `shipments`
--

DROP TABLE IF EXISTS `shipments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shipments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `no_resi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_duplicate_no_resi` tinyint(1) NOT NULL DEFAULT '0',
  `nomor_redock` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_order` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_sekolah` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_penerima` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provinsi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `daerah` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kota_kabupaten` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kecamatan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vendor_mm` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kode_funder` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_funder` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vendor_lm` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_manifest` date DEFAULT NULL,
  `koli` int DEFAULT NULL,
  `tgl_ho_sartrans` date DEFAULT NULL,
  `completed_date` date DEFAULT NULL,
  `tgl_sampai_kota_tujuan` date DEFAULT NULL,
  `sla_threshold_days` int DEFAULT NULL,
  `status_akhir` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_instalasi` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stagging` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sla` int DEFAULT NULL,
  `sla_due_date` date DEFAULT NULL,
  `sla_result` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bast_tgl_balik` date DEFAULT NULL,
  `bast_tgl_ke_finance` date DEFAULT NULL,
  `bast_keterangan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `harga_per_shipment` decimal(15,2) DEFAULT NULL,
  `status_invoice` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `shipments_nama_funder_tanggal_manifest_index` (`nama_funder`,`tanggal_manifest`),
  KEY `shipments_nama_funder_status_akhir_index` (`nama_funder`,`status_akhir`),
  KEY `shipments_nama_sekolah_index` (`nama_sekolah`),
  KEY `shipments_provinsi_index` (`provinsi`),
  KEY `shipments_nama_funder_index` (`nama_funder`),
  KEY `shipments_vendor_lm_index` (`vendor_lm`),
  KEY `shipments_tanggal_manifest_index` (`tanggal_manifest`),
  KEY `shipments_completed_date_index` (`completed_date`),
  KEY `shipments_status_akhir_index` (`status_akhir`),
  KEY `shipments_stagging_index` (`stagging`),
  KEY `shipments_sla_result_index` (`sla_result`),
  KEY `shipments_tgl_ho_sartrans_index` (`tgl_ho_sartrans`),
  KEY `shipments_sla_due_date_index` (`sla_due_date`)
) ENGINE=InnoDB AUTO_INCREMENT=517687 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

